#!/usr/bin/env python3
"""
Amber Studio - audio-only YouTube player.

One command:  python amber_studio.py

* Installs every Python dependency it needs (including a private ffmpeg),
  so nothing has to be set up by hand.
* Runs a small local server and opens the UI in a native window.
* Single file: the interface and the icon are embedded below.
"""

import importlib.util
import os
import subprocess
import sys

# True when packaged with python-for-android / running on Android
IS_ANDROID = (
    "ANDROID_ARGUMENT" in os.environ
    or "ANDROID_ROOT" in os.environ
    or os.path.exists("/system/build.prop")
)

# A windowed (--noconsole) exe has no stdout/stderr; give prints somewhere harmless to go.
if sys.stdout is None:
    sys.stdout = open(os.devnull, "w")
if sys.stderr is None:
    sys.stderr = open(os.devnull, "w")

# ---------------------------------------------------------------------------
# 1. Self-installing dependencies
# ---------------------------------------------------------------------------

REQUIRED = {
    "flask": "flask",
    "yt_dlp": "yt-dlp",
    "requests": "requests",
}
# Desktop-only extras (not used on Android)
if not IS_ANDROID:
    REQUIRED["webview"] = "pywebview"
    REQUIRED["imageio_ffmpeg"] = "imageio-ffmpeg"
    REQUIRED["mutagen"] = "mutagen"      # lets yt-dlp put cover art into .opus files



def _pip(*args):
    base = [sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check"]
    try:
        subprocess.check_call(base + list(args))
        return True
    except subprocess.CalledProcessError:
        pass
    # Some distros mark the system Python as "externally managed" (PEP 668).
    try:
        subprocess.check_call(base + ["--break-system-packages"] + list(args))
        return True
    except subprocess.CalledProcessError:
        pass
    # Last resort: per-user install (no admin rights needed).
    try:
        subprocess.check_call(base + ["--user", "--break-system-packages"] + list(args))
        return True
    except subprocess.CalledProcessError:
        return False


def _is_installed(mod: str) -> bool:
    if mod in sys.modules:
        return True
    try:
        return importlib.util.find_spec(mod) is not None
    except (ValueError, ImportError):
        return False


def ensure_dependencies():
    if IS_ANDROID or getattr(sys, "frozen", False):   # Android / Chaquopy: packages are bundled
        return
    missing = [pip_name for mod, pip_name in REQUIRED.items() if not _is_installed(mod)]
    if not missing:
        return
    print(f"[amber] First run: installing {', '.join(missing)} ...")
    if not _pip(*missing):
        print("[amber] Could not install automatically. Run this once, then start again:")
        print(f"        {sys.executable} -m pip install {' '.join(missing)}")
        sys.exit(1)
    importlib.invalidate_caches()
    print("[amber] Done.")


ensure_dependencies()

