_js_rt_cache = None


def _js_runtimes():
    """JS engines yt-dlp can use to solve YouTube's signature / n challenges. yt-dlp only enables deno on its own,
    so Node / Bun / QuickJS are switched on here when they are installed. Returns {} when none is found."""
    global _js_rt_cache
    if _js_rt_cache is None:
        found = {}
        for name in ("deno", "node", "bun", "quickjs"):
            try:
                if shutil.which(name):
                    found[name] = {}
            except Exception:
                pass
        _js_rt_cache = found
    return _js_rt_cache


def _ydl(opts):
    """yt_dlp.YoutubeDL with the installed JS runtimes switched on (looked up at call time, so an in-app update is used)."""
    o = dict(opts)
    rt = _js_runtimes()
    if rt and "js_runtimes" not in o:
        o["js_runtimes"] = rt
    return yt_dlp.YoutubeDL(o)


def _ver_key(v):
    """'2026.08.19' and '2026.8.19' are the same release (PyPI drops the zero): compare as numbers."""
    return tuple(int(x) for x in re.findall(r"\d+", str(v or "")))


