_file_lock = threading.RLock()


def _read_json(path: Path, default):
    with _file_lock:
        for candidate in (path, path.with_suffix(path.suffix + ".bak")):
            try:
                return json.loads(candidate.read_text(encoding="utf-8"))
            except (OSError, ValueError, UnicodeError):
                pass
    return default


def _write_json(path: Path, obj):
    with _file_lock:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(json.dumps(obj, indent=2, ensure_ascii=False, allow_nan=False), encoding="utf-8")
        # Keep the previous valid version; never back up corrupt state over it.
        if path.exists():
            try:
                json.loads(path.read_text(encoding="utf-8"))
                backup = path.with_suffix(path.suffix + ".bak")
                bt = backup.with_suffix(backup.suffix + ".tmp")
                shutil.copyfile(path, bt)
                bt.replace(backup)
            except (OSError, ValueError, UnicodeError):
                pass
        tmp.replace(path)   # atomic on every OS: a crash can't leave half a file


def load_config():
    cfg = _read_json(CONFIG_FILE, {})
    return cfg if isinstance(cfg, dict) else {}


def save_config(cfg: dict):
    _write_json(CONFIG_FILE, cfg)


DEFAULT_DATA = {"liked": [], "recent": [], "queue": []}


def _clean_tracks(items, limit=300):
    if not isinstance(items, list):
        return []
    out, seen = [], set()
    for item in items:
        if not isinstance(item, dict):
            continue
        vid = item.get("id")
        if not isinstance(vid, str) or not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", vid) or vid in seen:
            continue
        t = {"id": vid}
        for k, size in (("title", 500), ("sub", 300), ("cid", 128), ("dur", 32), ("filename", 240)):
            if isinstance(item.get(k), str):
                t[k] = item[k][:size]
        if "filename" in t and Path(t["filename"]).name != t["filename"]:
            t.pop("filename")
        thumb = item.get("thumb", "")
        if isinstance(thumb, str) and (thumb.startswith(("https://", "http://", "/api/art")) or not thumb):
            t["thumb"] = thumb[:4096]
        local = item.get("localUrl", "")
        if isinstance(local, str) and local.startswith("/api/downloads/"):
            t["localUrl"] = local[:1024]
        t["live"] = item.get("live") is True
        out.append(t); seen.add(vid)
        if len(out) >= limit:
            break
    return out


def _clean_session(session):
    session = session if isinstance(session, dict) else {}
    try:
        pos = float(session.get("position", 0))
        if not 0 <= pos <= 86400:
            pos = 0
    except (TypeError, ValueError, OverflowError):
        pos = 0
    tab = session.get("tab")
    repeat = session.get("repeat", 0)
    return {"track_id": str(session.get("track_id", ""))[:128], "position": pos,
            "tab": tab if tab in ("home", "player", "browse", "library", "download", "mic", "setup") else "home",
            "shuffle": session.get("shuffle") is True, "repeat": repeat if type(repeat) is int and repeat in (0, 1, 2) else 0}


def load_data():
    d = _read_json(DATA_FILE, {})
    if not isinstance(d, dict):
        d = {}
    for k in DEFAULT_DATA:
        d[k] = _clean_tracks(d.get(k), 50 if k == "recent" else 300)
    d["session"] = _clean_session(d.get("session"))
    if type(d.get("revision")) is not int:
        d["revision"] = 0
    return d


def save_data(d: dict):
    _write_json(DATA_FILE, d)


# ---------------------------------------------------------------------------
# Access gate: the shared key list (and so search) stays locked until the
# password is entered in Setup. Only a salted PBKDF2 hash is stored here, never
# the password itself. Pasting a YouTube link always works without unlocking.
# ---------------------------------------------------------------------------

UNLOCK_SALT = bytes.fromhex("d2f96fcf6b8da286aa55e51799187873")
UNLOCK_HASH = "a050af4b977569483caaca2851112a54d8f65031608d7cd52e60202226feaac4"
UNLOCK_ITERATIONS = 200000

_unlock_lock = threading.Lock()
_unlock_fail = {"count": 0, "until": 0.0}


def _derive(password: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), UNLOCK_SALT, UNLOCK_ITERATIONS).hex()


def _unlock_token(install_id: str) -> str:
    return hmac.new(bytes.fromhex(UNLOCK_HASH), install_id.encode("utf-8"), hashlib.sha256).hexdigest()


def is_unlocked() -> bool:
    cfg = load_config()
    iid, tok = cfg.get("install_id"), cfg.get("unlock_token")
    return bool(iid and tok and hmac.compare_digest(str(tok), _unlock_token(str(iid))))


# ---------------------------------------------------------------------------
# 4. ffmpeg: use the system one if present, otherwise the bundled one
# ---------------------------------------------------------------------------

_ffmpeg_path = None
_ffmpeg_lock = threading.Lock()


def find_ffmpeg():
    """Return a usable ffmpeg executable path, or None. Result is cached."""
    global _ffmpeg_path
    with _ffmpeg_lock:
        if _ffmpeg_path and Path(_ffmpeg_path).exists():
            return _ffmpeg_path
        if IS_ANDROID:
            try:
                from com.chaquo.python import Python
                context = Python.getPlatform().getApplication()
                lib_dir = Path(context.getApplicationInfo().nativeLibraryDir)
                for cand in (lib_dir / "libffmpeg.so", lib_dir / "ffmpeg"):
                    if cand.exists():
                        _ffmpeg_path = str(cand)
                        return str(cand)
            except Exception:
                pass
        ff_dir = os.environ.get("AMBER_FFMPEG_DIR")
        if ff_dir and Path(ff_dir).exists():
            p_dir = Path(ff_dir)
            if p_dir.is_file():
                _ffmpeg_path = str(p_dir)
                return str(p_dir)
            lib_ff = p_dir / "libffmpeg.so"
            if lib_ff.exists():
                _ffmpeg_path = str(lib_ff)
                return str(lib_ff)
            ff_exe = p_dir / "ffmpeg"
            if ff_exe.exists():
                _ffmpeg_path = str(ff_exe)
                return str(ff_exe)
            bin_dir = p_dir / "ffbin"
            if bin_dir.exists():
                if (bin_dir / "libffmpeg.so").exists():
                    _ffmpeg_path = str(bin_dir / "libffmpeg.so")
                    return str(bin_dir / "libffmpeg.so")
                if (bin_dir / "ffmpeg").exists():
                    _ffmpeg_path = str(bin_dir / "ffmpeg")
                    return str(bin_dir / "ffmpeg")
        found = shutil.which("ffmpeg")
        if found:
            _ffmpeg_path = found
            return found
        try:
            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            if exe and Path(exe).exists():
                if os.name != "nt":
                    try:
                        os.chmod(exe, 0o755)
                    except OSError:
                        pass
                _ffmpeg_path = exe
                return exe
        except Exception:
            pass
        return None


# ---------------------------------------------------------------------------
# 5. YouTube API key pool  (manual key + shared list from GitHub)
# ---------------------------------------------------------------------------

http_session = requests.Session()
http_session.headers.update({"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"})

KEY_RE = re.compile(r"^AIza[0-9A-Za-z_\-]{35}$")


class KeyPool:
    """
    Keys come from (in priority order):
      1. the key the user pasted in Settings
      2. the shared list at KEYS_URL (one key per line, '#' comments allowed)

    When Google reports a key is out of quota, it is parked until the next
    Pacific-time midnight (when YouTube resets quotas) and the next key is used.
    """

    def __init__(self):
        self.lock = threading.Lock()
        self.remote = []            # keys fetched from KEYS_URL
        self.fetched_at = 0.0
        self.fetch_error = ""
        self.dead = {}              # key -> reason
        self.dead_day = self._today()

    @staticmethod
    def _today():
        # YouTube quota resets at midnight Pacific. UTC-8 is a safe approximation.
        return datetime.fromtimestamp(time.time() - 8 * 3600, tz=timezone.utc).strftime("%Y-%m-%d")

    def _roll_day(self):
        today = self._today()
        if today != self.dead_day:
            self.dead.clear()
            self.dead_day = today

    @staticmethod
    def parse(text: str):
        keys = []
        for line in (text or "").replace("\ufeff", "").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if KEY_RE.match(line) and line not in keys:
                keys.append(line)
        return keys

    def refresh(self, force=False):
        if not is_unlocked():                 # locked: never fetch or hold the shared keys
            with self.lock:
                self.remote = []
                self.fetch_error = ""
            return
        with self.lock:
            fresh = (time.time() - self.fetched_at) < KEYS_REFRESH_SECONDS
            if fresh and not force and (self.remote or self.fetch_error == ""):
                return
        try:
            r = requests.get(KEYS_URL, timeout=10, headers={"Cache-Control": "no-cache"})
            r.raise_for_status()
            keys = self.parse(r.text)
            with self.lock:
                self.remote = keys
                self.fetched_at = time.time()
                self.fetch_error = "" if keys else "The key file was reachable but contains no valid keys."
        except Exception as e:
            with self.lock:
                self.fetched_at = time.time() - KEYS_REFRESH_SECONDS + 60   # retry in a minute
                self.fetch_error = f"Could not fetch the key list: {str(e)[:120]}"

    def candidates(self):
        """Ordered list of keys worth trying right now."""
        self.refresh()
        with self.lock:
            self._roll_day()
            manual = load_config().get("youtube_api_key", "").strip()
            ordered = []
            for k in ([manual] if manual else []) + self.remote:
                if k and k not in ordered and k not in self.dead:
                    ordered.append(k)
            return ordered

    def mark_dead(self, key, reason):
        with self.lock:
            self.dead[key] = reason

    def status(self):
        self.refresh()
        with self.lock:
            self._roll_day()
            manual = load_config().get("youtube_api_key", "").strip()
            total = len(self.remote) + (1 if manual and manual not in self.remote else 0)
            alive = total - len([k for k in self.dead
                                 if k == manual or k in self.remote])
            return {
                "has_key": total > 0,
                "locked": not is_unlocked(),
                "total": total,
                "alive": max(alive, 0),
                "has_manual": bool(manual),
                "manual_masked": ("\u2022\u2022\u2022\u2022" + manual[-4:]) if len(manual) >= 4 else "",
                "remote_count": len(self.remote),
                "fetch_error": self.fetch_error,
            }


keys = KeyPool()

QUOTA_REASONS = {"quotaExceeded", "dailyLimitExceeded", "rateLimitExceeded", "userRateLimitExceeded"}
BAD_KEY_REASONS = {"keyInvalid", "keyExpired", "ipRefererBlocked", "forbidden", "accessNotConfigured"}


class YTError(Exception):
    def __init__(self, code, detail=""):
        super().__init__(detail or code)
        self.code = code
        self.detail = detail


def yt_get(endpoint: str, params: dict):
    """Call the YouTube Data API, rotating through keys when one is exhausted."""
    cands = keys.candidates()
    if not cands:
        st = keys.status()
        if st.get("locked"):
            raise YTError("locked", "Search is locked. Paste a YouTube link to play it, or unlock search in Setup.")
        raise YTError("no_api_key", st.get("fetch_error", ""))

    last_reason, last_msg = "", ""
    for key in cands:
        try:
            resp = requests.get(
                f"https://www.googleapis.com/youtube/v3/{endpoint}",
                params={**params, "key": key},
                timeout=10,
            )
            data = resp.json()
        except Exception as e:
            raise YTError("network", str(e)[:160])

        err = data.get("error")
        if not err:
            return data

        reasons = {e.get("reason") for e in err.get("errors", []) if isinstance(e, dict)}
        last_msg = err.get("message", "")
        last_reason = next(iter(reasons), "unknown")
        if reasons & QUOTA_REASONS:
            keys.mark_dead(key, "quota")
            continue
        if reasons & BAD_KEY_REASONS or err.get("code") in (400, 403) and "key" in last_msg.lower():
            keys.mark_dead(key, last_reason)
            continue
        raise YTError("api_error", last_msg)     # a real request error: rotating won't help

    if last_reason in QUOTA_REASONS:
        raise YTError("quota", "Every available API key is out of quota for today. Try again tomorrow, or paste a link.")
    if last_reason == "ipRefererBlocked":
        raise YTError("key_blocked", "The shared keys are restricted to a website, so they can't be used from this app. "
                                     "Remove the HTTP-referrer restriction in Google Cloud, or paste your own key in Setup.")
    raise YTError("api_error", last_msg or "All API keys were rejected.")


