body #tab-player .meta,body #tab-player .seek,body #tab-player .times,body #tab-player .controls,body #tab-player .tools,body #tab-player .avseg{flex-shrink:0;min-width:0}
body #tab-player .t-title{font-size:clamp(22px,2.4vw,32px);line-height:1.22;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere;margin:0}
