body #tab-player .qcol{display:flex;flex-direction:column;min-height:0;height:100%;max-height:100%;min-width:0;flex:1 1 0;padding:0;overflow:hidden;clip-path:none}
body #tab-player .qcol .section-title{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;margin:0;padding:16px;border-bottom:1px solid var(--line2);font-size:17px;flex:none}
