body #tab-player .list.q{display:flex;flex-direction:column;flex:1 1 0;min-height:0;height:auto;max-height:none;overflow-y:auto!important;overflow-x:hidden;padding:8px;gap:4px;mask:none!important;-webkit-mask:none!important;scrollbar-width:thin;scrollbar-color:var(--line2) transparent;overscroll-behavior:contain;scrollbar-gutter:stable}
body #tab-player .list.q .row{flex:none;min-height:68px;padding:10px;gap:10px;border-radius:12px;min-width:0}
