app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 100 * 1024 * 1024
app.config["JSON_AS_ASCII"] = False

_cache_lock = threading.Lock()
_stream_cache = {}
CACHE_TTL_SECONDS = 60 * 50
_channel_cache = {}


def _evict_expired_caches():
    now = time.time()
    expired_streams = [k for k, v in _stream_cache.items() if v.get("expires_at", 0) <= now]
    for k in expired_streams:
        _stream_cache.pop(k, None)
    expired_channels = [k for k, v in _channel_cache.items() if now - v.get("at", 0) >= 6 * 3600]
    for k in expired_channels:
        _channel_cache.pop(k, None)


def get_stream_cache(video_id: str):
    with _cache_lock:
        _evict_expired_caches()
        cached = _stream_cache.get(video_id)
        if cached and cached.get("expires_at", 0) > time.time():
            return cached
        return None


def set_stream_cache(video_id: str, entry: dict):
    with _cache_lock:
        _evict_expired_caches()
        _stream_cache[video_id] = entry


def pop_stream_cache(video_id: str):
    with _cache_lock:
        _evict_expired_caches()
        return _stream_cache.pop(video_id, None)


def get_stream_cache_duration(video_id: str):
    with _cache_lock:
        entry = _stream_cache.get(video_id)
        return entry.get("duration") if entry else None


def get_channel_cache(channel_id: str):
    with _cache_lock:
        _evict_expired_caches()
        hit = _channel_cache.get(channel_id)
        if hit and time.time() - hit.get("at", 0) < 6 * 3600:
            return hit
        return None


def set_channel_cache(channel_id: str, info: dict):
    with _cache_lock:
        _evict_expired_caches()
        _channel_cache[channel_id] = info
_download_jobs = {}
_jobs_lock = threading.Lock()
_download_queue = []
_download_active = 0
MAX_CONCURRENT_DOWNLOADS = 2


def _pump_downloads():
    global _download_active
    with _jobs_lock:
        while _download_active < MAX_CONCURRENT_DOWNLOADS and _download_queue:
            vid, title = _download_queue.pop(0)
            job = _download_jobs.get(vid)
            if job and job.get("status") in ("downloading", "done"):
                continue
            existing = find_download(vid)
            if existing:
                _download_jobs[vid] = {"status": "done", "progress": 100, "filename": existing.name, "error": None}
                continue
            _download_active += 1
            _download_jobs[vid] = {"status": "downloading", "progress": 0, "filename": None, "error": None}
            threading.Thread(target=_run_download_wrapped, args=(vid, title), daemon=True).start()


def _run_download_wrapped(video_id: str, title: str):
    global _download_active
    try:
        run_download(video_id, title)
    finally:
        with _jobs_lock:
            _download_active = max(0, _download_active - 1)
        _pump_downloads()



@app.after_request
def _api_no_cache(resp):
    p = request.path
    if p.startswith("/api/") and not p.startswith(("/api/art", "/api/downloads/")):
        resp.headers["Cache-Control"] = "no-store"
    return resp


@app.before_request
def _same_origin_only():
    """Other web pages in the user's browser must not be able to drive the local API (lock, delete, download...)."""
    host = (request.host or "").rsplit(":", 1)[0].strip("[]").lower()
    if host not in ("127.0.0.1", "localhost", "::1"):
        return Response("Bad host", status=403)
    origin = request.headers.get("Origin")
    if origin == "null" or request.headers.get("Sec-Fetch-Site") == "cross-site":
        return Response("Bad origin", status=403)
    if origin:
        oh = (urlparse(origin).hostname or "").lower()
        if oh not in ("127.0.0.1", "localhost", "::1") or (urlparse(origin).port or 80) != (urlparse("http://" + request.host).port or 80):
            return Response("Bad origin", status=403)
    if request.method in ("POST", "PUT", "PATCH") and request.is_json and not isinstance(request.get_json(silent=True), dict):
        return jsonify({"error": "bad_request", "detail": "Expected a JSON object"}), 400
    return None


@app.errorhandler(Exception)
def _api_errors(e):
    from werkzeug.exceptions import HTTPException
    if isinstance(e, HTTPException):
        return e
    print(f"[amber] error in {request.path}: {e!r}")
    if request.path.startswith("/api/"):
        return jsonify({"error": "server_error", "detail": str(e)[:200]}), 500
    return Response("Internal error", status=500)


@app.route("/")
def index():
    # Optional deployment-owned ICE servers. Never bundle third-party relay passwords.
    markup = FRONTEND_HTML
    raw_rtc = os.environ.get("AMBER_STUDIO_RTC_CONFIG", "")
    if raw_rtc:
        try:
            rtc = json.loads(raw_rtc)
            if not isinstance(rtc, dict) or not isinstance(rtc.get("iceServers"), list):
                raise ValueError("Expected an iceServers array")
            payload = json.dumps(rtc).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
            markup = markup.replace("</head>", "<script>window.AMBER_RTC_CONFIG=" + payload + ";</script></head>", 1)
        except (ValueError, TypeError):
            print("[amber] Invalid AMBER_STUDIO_RTC_CONFIG; using built-in STUN servers")
    resp = Response(markup, mimetype="text/html")
    resp.headers["Cache-Control"] = "no-store"
    return resp


def _art_candidates(u, hi):
    """Biggest-first list of picture URLs for one cover (same hosts only)."""
    import re
    out = []
    if hi:
        m = re.match(r"^https?://i\d?\.ytimg\.com/vi(?:_webp)?/([\w-]{6,})/", u)
        if m:
            b = "https://i.ytimg.com/vi/%s/" % m.group(1)
            out += [b + "maxresdefault.jpg", b + "hq720.jpg", b + "sddefault.jpg", b + "hqdefault.jpg"]
        elif re.search(r"=(?:w\d+-h\d+|s\d+)[^=/]*$", u):
            out += [re.sub(r"=(?:w\d+-h\d+|s\d+)[^=/]*$", sz, u) for sz in ("=w1600-h1600-l100-rj", "=w1000-h1000-l95-rj")]
    out.append(u)
    return list(dict.fromkeys(out))


@app.route("/api/art")
def art_proxy():
    from urllib.parse import urlparse
    u = request.args.get("u", "")
    hi = request.args.get("hi") == "1"
    host = (urlparse(u).hostname or "").lower()
    if urlparse(u).scheme not in ("http", "https") or not (
        host.endswith(".ytimg.com") or host.endswith(".ggpht.com") or host.endswith(".googleusercontent.com") or host == "i.ytimg.com"
    ):
        return jsonify({"error": "bad_url"}), 400
    try:
        cands = _art_candidates(u, hi)
        for i, c in enumerate(cands):
            last = i == len(cands) - 1
            try:
                r = requests.get(c, timeout=8, headers={"User-Agent": "Mozilla/5.0"})
            except Exception:
                if last:
                    raise
                continue
            # a missing size comes back as a tiny grey placeholder: skip it and try the next size
            if r.ok and (last or len(r.content) > 2500):
                resp = Response(r.content, mimetype=r.headers.get("content-type", "image/jpeg"))
                resp.headers["Cache-Control"] = "public, max-age=86400"
                return resp
        return Response(b"", status=404)
    except Exception:
        return Response(b"", status=502)


VENDOR_FILES = {"peerjs.min.js", "qrcode.js"}


@app.route("/vendor/<name>")
def vendor_file(name):
    """Bundled PeerJS + QR libraries for the Phone remote (so it works without a CDN)."""
    if name not in VENDOR_FILES:
        return Response("Not found", status=404)
    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))
    try:
        data = (base / "vendor" / name).read_bytes()
    except Exception:
        return Response("Not found", status=404)
    resp = Response(data, mimetype="application/javascript")
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


