@app.route("/api/config", methods=["POST"])
def set_config():
    data = request.get_json(force=True, silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "bad_request"}), 400
    key = str(data.get("youtube_api_key") or "").strip()
    with _file_lock:
        cfg = load_config()
        if data.get("clear"):
            cfg.pop("youtube_api_key", None)
            save_config(cfg)
            return jsonify({"ok": True})
        if not key:
            return jsonify({"ok": False, "error": "empty key"}), 400
        if not KEY_RE.match(key):
            return jsonify({"ok": False, "error": "That doesn't look like a YouTube API key (it should start with AIza and be 39 characters)."}), 400
        cfg["youtube_api_key"] = key
        save_config(cfg)
    return jsonify({"ok": True})


@app.route("/api/config/refresh", methods=["POST"])
def refresh_keys():
    keys.refresh(force=True)
    return jsonify(keys.status())


@app.route("/api/unlock", methods=["POST"])
def unlock():
    data = request.get_json(force=True, silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "bad_request"}), 400
    password = str(data.get("password") or "")
    with _unlock_lock:
        wait = _unlock_fail["until"] - time.time()
    if wait > 0:
        return jsonify({"ok": False, "error": f"Too many attempts. Try again in {int(wait) + 1} seconds."}), 429
    if not hmac.compare_digest(_derive(password), UNLOCK_HASH):
        with _unlock_lock:
            _unlock_fail["count"] += 1
            if _unlock_fail["count"] >= 5:
                _unlock_fail.update(count=0, until=time.time() + 30)
        return jsonify({"ok": False, "error": "Wrong password."}), 401
    with _unlock_lock:
        _unlock_fail.update(count=0, until=0.0)
    with _file_lock:
        cfg = load_config()
        iid = cfg.get("install_id") or secrets.token_hex(16)
        cfg["install_id"] = iid
        cfg["unlock_token"] = _unlock_token(iid)
        save_config(cfg)
    keys.refresh(force=True)
    return jsonify({"ok": True, **keys.status()})


@app.route("/api/lock", methods=["POST"])
def lock_again():
    cfg = load_config()
    cfg.pop("unlock_token", None)
    save_config(cfg)
    keys.refresh(force=True)                  # locked now, so this clears the shared keys from memory
    return jsonify({"ok": True, **keys.status()})


