def run_flask():
    import logging
    logging.getLogger("werkzeug").setLevel(logging.ERROR)
    app.run(host="127.0.0.1", port=PORT, debug=False, use_reloader=False, threaded=True)


def _wait_for_server(timeout=8.0):
    end = time.monotonic() + timeout
    while time.monotonic() < end:
        try:
            r = requests.get(f"http://127.0.0.1:{PORT}/api/identity", timeout=0.5)
            d = r.json() if r.ok else {}
            if d.get("app_id") == APP_ID and d.get("instance") == SERVER_INSTANCE:
                return True
        except Exception:
            pass
        time.sleep(0.15)
    return False


def _write_icon():
    """Write the embedded icon to a temp file so the OS window can load it."""
    import base64, tempfile
    path = BASE_DIR / "app_icon.ico"
    try:
        path.write_bytes(base64.b64decode(ICON_ICO_B64))
        return str(path)
    except OSError:
        return None


def _set_windows_icon(ico_path, title=APP_NAME):
    """Give the running window (and its taskbar button) the Amber icon on Windows."""
    if os.name != "nt" or not ico_path:
        return
    try:
        import ctypes
        user32 = ctypes.windll.user32
        user32.FindWindowW.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p]
        user32.FindWindowW.restype = ctypes.c_void_p
        user32.LoadImageW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p, ctypes.c_uint, ctypes.c_int, ctypes.c_int, ctypes.c_uint]
        user32.LoadImageW.restype = ctypes.c_void_p
        user32.SendMessageW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_size_t, ctypes.c_ssize_t]
        user32.SendMessageW.restype = ctypes.c_ssize_t
        hwnd = 0
        for _ in range(60):                      # wait up to ~6 s for the window to exist
            hwnd = user32.FindWindowW(None, title)
            if hwnd:
                break
            time.sleep(0.1)
        if not hwnd:
            return
        IMAGE_ICON, LR_LOADFROMFILE, WM_SETICON = 1, 0x10, 0x80
        small = user32.LoadImageW(None, ico_path, IMAGE_ICON, 16, 16, LR_LOADFROMFILE)
        big = user32.LoadImageW(None, ico_path, IMAGE_ICON, 256, 256, LR_LOADFROMFILE)
        if small:
            user32.SendMessageW(hwnd, WM_SETICON, 0, small)
        if big:
            user32.SendMessageW(hwnd, WM_SETICON, 1, big)
    except Exception as e:
        print(f"[amber] could not set window icon: {e}")


class _WindowApi:
    """Tiny bridge so the video player's Fullscreen button can use the whole screen, not only the window."""
    def __init__(self):
        self._fs = False

    def set_fullscreen(self, on):
        try:
            import webview
            on = bool(on)
            if on != self._fs:
                webview.windows[0].toggle_fullscreen()
                self._fs = on
        except Exception:
            pass
        return True


_instance_mutex = None


def _claim_window_instance():
    global _instance_mutex
    if os.name != "nt":
        return True
    import ctypes
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.CreateMutexW.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p]
    kernel.CreateMutexW.restype = ctypes.c_void_p
    handle = kernel.CreateMutexW(None, False, "Local\\" + APP_ID)
    if not handle:
        raise OSError("Could not reserve the application instance")
    if ctypes.get_last_error() == 183:
        kernel.CloseHandle.argtypes = [ctypes.c_void_p]
        kernel.CloseHandle(handle)
        user = ctypes.windll.user32
        user.FindWindowW.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p]
        user.FindWindowW.restype = ctypes.c_void_p
        user.ShowWindow.argtypes = [ctypes.c_void_p, ctypes.c_int]
        user.SetForegroundWindow.argtypes = [ctypes.c_void_p]
        hwnd = user.FindWindowW(None, APP_NAME)
        if hwnd:
            user.ShowWindow(hwnd, 9); user.SetForegroundWindow(hwnd)
        return False
    _instance_mutex = handle
    return True


def _release_window_instance():
    global _instance_mutex
    if _instance_mutex is not None and os.name == "nt":
        import ctypes
        kernel = ctypes.windll.kernel32
        kernel.CloseHandle.argtypes = [ctypes.c_void_p]
        kernel.CloseHandle(_instance_mutex)
        _instance_mutex = None


atexit.register(_release_window_instance)


def main():
    # Windows groups taskbar buttons by app id; without this it shows python.exe's icon.
    if os.name == "nt":
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_ID)
        except Exception:
            pass

    if not _claim_window_instance():
        return
    from werkzeug.serving import make_server
    try:
        server = make_server("127.0.0.1", PORT, app, threaded=True)
    except (OSError, SystemExit):
        _release_window_instance()
        message = f"{APP_NAME} could not use port {PORT}. Close its other running copy or set {APP_ENV}_PORT to a free port."
        if os.name == "nt":
            import ctypes
            ctypes.windll.user32.MessageBoxW(None, message, APP_NAME, 0x10)
        print(message)
        return
    atexit.register(server.server_close)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    if not _wait_for_server():
        print(f"[amber] ERROR: the local server did not start (is port {PORT} already in use?)")
        print(f"        Set another port with:  {APP_ENV}_PORT=8890 python {Path(__file__).name}")
        sys.exit(1)

    # Prepare ffmpeg and the key list in the background so the first download / search is instant.
    threading.Thread(target=find_ffmpeg, daemon=True).start()
    threading.Thread(target=keys.refresh, daemon=True).start()

    import webview
    try:
        webview.settings["ALLOW_DOWNLOADS"] = True
    except Exception:
        pass
    ico = _write_icon()
    webview.create_window(APP_NAME, f"http://127.0.0.1:{PORT}/", width=1180, height=760,
                          min_size=(360, 600), background_color="#121315", js_api=_WindowApi())
    # Keep the window's saved options (low-power, glow, volume, speed ...) between runs: pywebview
    # starts in private mode by default, which throws localStorage away every time the app closes.
    store = BASE_DIR / "webview_data"
    try:
        store.mkdir(exist_ok=True)
    except Exception:
        pass
    try:
        try:
            webview.start(_set_windows_icon, (ico,), icon=ico, private_mode=False, storage_path=str(store))
        except TypeError:
            try:
                webview.start(_set_windows_icon, (ico,), icon=ico)   # icon= is used by the GTK/Qt backends
            except TypeError:
                webview.start(_set_windows_icon, (ico,))
    finally:
        HOLD.release_all()
        server.shutdown(); server.server_close()
        _release_window_instance()


if __name__ == "__main__":
    main()
